File file = new File("C:\\weaver\\nfs\\MULTIPART_EVENT\\2.txt");
CloseableHttpClient httpClient = HttpClients.createDefault();
String fileName = file.getName();
// 开放平台接口请求地址
HttpPost httpPost = new HttpPost("http://192.168.51.27:20600/papi/openapi/api/file/v2/common/upload?access_token=89fca5465cc48d5b9c6e43ad594d58a0");
//HttpEntity builder
MultipartEntityBuilder builder = MultipartEntityBuilder.create();
//字符编码
builder.setCharset(StandardCharsets.UTF_8);
//模拟浏览器
builder.setMode(HttpMultipartMode.BROWSER_COMPATIBLE);
builder.setContentType(ContentType.MULTIPART_FORM_DATA);
builder.addPart("file", new FileBody(file, ContentType.DEFAULT_BINARY));
builder.addTextBody("name", fileName, ContentType.MULTIPART_FORM_DATA);
builder.addTextBody("userid", "811711878160941057", ContentType.MULTIPART_FORM_DATA);
builder.addTextBody("module", "workflow", ContentType.MULTIPART_FORM_DATA);
builder.addTextBody("size", String.valueOf(file.length()), ContentType.MULTIPART_FORM_DATA);
//HttpEntity
org.apache.http.HttpEntity entity = builder.build();
httpPost.setEntity(entity);
// 执行提交
HttpResponse response = httpClient.execute(httpPost);
//响应
org.apache.http.HttpEntity responseEntity = response.getEntity();
if (responseEntity != null) {
    // 将响应内容转换为字符串
    System.out.println(EntityUtils.toString(response.getEntity()));
}



